listitem.para:
It has been the default system and service manager in Red Hat
          Enterprise Linux and CentOS since version 7, and in Fedora since
          Fedora 15;

section.programlisting:
modules {
    acct_rtcp_hep {
        capt_host = 192.0.2.10
        capt_port = 9060
        capt_ptype = udp
        capt_id = 101
    }
}

section.para:
where duration is in RTP timestamp
      units, and side is 0 for the caller and 1
      for the callee. For example:

section.programlisting:
#include <librtpproxy.h>

struct rtpp_cfg *rtpp_main(int argc, const char * const *argv);
void rtpp_shutdown(struct rtpp_cfg *);

#include <sys/socket.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#include <librtpproxy.h>

int
main(void)
{
    int fds[2];
    char fdarg[16], buf[256];
    struct rtpp_cfg *cfsp;
    ssize_t len;

    if (socketpair(AF_UNIX, SOCK_STREAM, 0, fds) != 0)
        return (1);
    snprintf(fdarg, sizeof(fdarg), "fd:%d", fds[1]);
    const char *argv[] = {"rtpproxy", "-s", fdarg, "-l", "127.0.0.1",
      "-d", "info"};
    cfsp = rtpp_main(sizeof(argv) / sizeof(argv[0]), argv);
    if (cfsp == NULL)
        return (1);

    const char *cmd = "U call1 127.0.0.1 12000 ftag1\n";
    write(fds[0], cmd, strlen(cmd));
    len = read(fds[0], buf, sizeof(buf) - 1);
    if (len > 0) {
        buf[len] = '\0';
        printf("allocated: %s", buf);
    }

    rtpp_shutdown(cfsp);
    close(fds[0]);
    return (0);
}
